  'inject.import.sampleContent': { 'zh-CN': '【第1章片段】\n{first}\n\n【最新章节片段】\n{latest}', 'en-US': '[Chapter 1 excerpt]\n{first}\n\n[Latest chapter excerpt]\n{latest}', 'ru-RU': '[Отрывок гл. 1]\n{first}\n\n[Отрывок последней главы]\n{latest}' },
